// Builds the new SEO pages (plan/02 Phase B and C) into site-seo/. Run from products/aurum-invoice:  node seo/seo-gen.js
// The pages use the same markup as the live ones, so launch/launch.js rewrites their header, buttons and wording the same way.
const fs = require("fs"), path = require("path");
const ROOT = path.join(__dirname, "..", "site-seo"), BASE = "https://auruminvoice.com.ng", TODAY = "2026-11-16", TODAY_TXT = "16 November 2026";
const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const slugify = (s) => s.toLowerCase().replace(/&amp;/g, "and").replace(/<[^>]+>/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
const FOOT = (() => { const h = fs.readFileSync(path.join(ROOT, "guides/invoice-for-photographers-nigeria/index.html"), "utf8"); return h.slice(h.indexOf("<footer")); })();
const CTA_SECTION = (() => { const h = fs.readFileSync(path.join(ROOT, "guides/invoice-for-photographers-nigeria/index.html"), "utf8"); const i = h.indexOf('<section class="cta">'); return h.slice(i, h.indexOf("</section>", i) + 10); })();
const MID = '<aside class="mid-cta"><div><b>See it before you pay.</b><span>Open a sample wax-sealed invoice in the free demo. Sample data, nothing to pay.</span></div><a class="btn primary" href="/app/" data-cta="demo" data-where="mid">Try the free demo</a></aside>';
const pages = [];
const page = (p) => pages.push(p);

function render(p) {
  const url = BASE + p.path, og = BASE + "/og/" + (p.og || "guides") + ".jpg";
  const secs = p.sections.map((s) => ({ ...s, id: s.id || slugify(s.h2) }));
  const toc = secs.length > 2 ? '<nav class="toc" aria-label="On this page"><b>On this page</b><ol>' + secs.map((s) => '<li><a href="#' + s.id + '">' + s.h2 + "</a></li>").join("") + "</ol></nav>\n" : "";
  const crumbs = p.crumbs; // [[href,label],...] then current
  const ld = { "@context": "https://schema.org", "@graph": [
    { "@type": p.kind === "tool" ? "WebApplication" : p.kind === "product" ? "WebPage" : "Article", "@id": url + "#page", ...(p.kind === "tool" ? { name: p.h1, applicationCategory: "BusinessApplication", operatingSystem: "Any", offers: { "@type": "Offer", price: "0", priceCurrency: "NGN" } } : { headline: p.h1 }), description: p.desc, datePublished: TODAY, dateModified: TODAY, inLanguage: "en-NG", image: og, mainEntityOfPage: url, author: { "@id": BASE + "/#org" }, publisher: { "@id": BASE + "/#org" }, isPartOf: { "@id": BASE + "/#site" } },
    { "@type": "Organization", "@id": BASE + "/#org", name: "Aurum Invoice Studio", url: BASE + "/", logo: BASE + "/icons/icon-512.png", description: "Invoice, receipt and quotation app for Nigerian businesses.", sameAs: ["https://www.facebook.com/profile.php?id=1527108630475190", "https://www.instagram.com/auruminvoice"] },
    { "@type": "WebSite", "@id": BASE + "/#site", url: BASE + "/", name: "Aurum Invoice Studio", inLanguage: "en-NG", publisher: { "@id": BASE + "/#org" } },
    { "@type": "BreadcrumbList", itemListElement: [...crumbs.map(([h, l], i) => ({ "@type": "ListItem", position: i + 1, name: l, item: BASE + h })), { "@type": "ListItem", position: crumbs.length + 1, name: p.crumb, item: url }] },
    ...(p.faq && p.faq.length ? [{ "@type": "FAQPage", mainEntity: p.faq.map(([q, a]) => ({ "@type": "Question", name: q, acceptedAnswer: { "@type": "Answer", text: a.replace(/<[^>]+>/g, "") } })) }] : []),
  ] };
  const head = '<!doctype html>\n<html lang="en-NG">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">\n<title>' + esc(p.title) + '</title>\n<meta name="description" content="' + esc(p.desc) + '">\n<link rel="canonical" href="' + url + '">\n<meta name="robots" content="index, follow, max-image-preview:large, max-snippet:-1">\n<meta name="theme-color" content="#0E0C0A">\n<meta property="og:site_name" content="Aurum Invoice Studio">\n<meta property="og:type" content="article">\n<meta property="og:title" content="' + esc(p.title) + '">\n<meta property="og:description" content="' + esc(p.desc) + '">\n<meta property="og:url" content="' + url + '">\n<meta property="og:image" content="' + og + '">\n<meta property="og:image:width" content="1200"><meta property="og:image:height" content="630">\n<meta property="og:locale" content="en_NG">\n<meta name="twitter:card" content="summary_large_image">\n<meta name="twitter:title" content="' + esc(p.title) + '">\n<meta name="twitter:description" content="' + esc(p.desc) + '">\n<meta name="twitter:image" content="' + og + '">\n<link rel="icon" type="image/png" href="/icons/favicon-64.png">\n<link rel="apple-touch-icon" href="/icons/apple-touch-icon.png">\n<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,500;0,600;1,500&family=Manrope:wght@400;500;600;700;800&display=swap">\n<link rel="stylesheet" href="/seo.css">\n<script type="application/ld+json">' + JSON.stringify(ld) + '</script>\n<script src="/seo.js" defer></script>\n</head>\n<body>\n<header class="top"><div class="wrap bar">\n  <a class="brand" href="/" aria-label="Aurum Invoice Studio, home"><span class="mark">Au</span><span class="name">AURUM</span></a>\n  <nav aria-label="Main"><a href="/guides/">Guides</a><a href="/#pricing">Pricing</a><a class="btn sm" href="/#pricing" data-cta="buy" data-where="header">Get Aurum</a></nav>\n</div></header>\n<main class="wrap page">\n';
  const crumbHtml = '<nav class="crumbs" aria-label="Breadcrumb">' + [...crumbs.map(([h, l]) => '<a href="' + h + '">' + l + "</a>"), "<span>" + p.crumb + "</span>"].join(" <span>/</span> ") + "</nav>\n";
  const body = crumbHtml + "<h1>" + p.h1 + '</h1>\n<p class="meta">Updated ' + TODAY_TXT + (p.read ? " &middot; " + p.read + " min read" : "") + '</p>\n<p class="lead">' + p.lead + "</p>\n\n" + toc +
    secs.map((s, i) => '<section id="' + s.id + '"><h2>' + s.h2 + "</h2>" + s.html + "</section>" + (i === 0 && !p.noMid ? "\n" + MID : "")).join("\n") + "\n" +
    (p.disclaimer ? '<p class="callout"><b>Please note:</b> ' + p.disclaimer + "</p>\n" : "") +
    (p.faq && p.faq.length ? '<section id="faq"><h2>Questions people ask</h2><div class="faq">' + p.faq.map(([q, a]) => "<details><summary>" + q + "</summary><p>" + a + "</p></details>").join("") + "</div></section>\n" : "") +
    '<section class="share"><b>Found this useful? Share it with another business owner:</b><div><a class="btn" href="https://wa.me/?text=' + encodeURIComponent(p.h1 + " " + url) + '" target="_blank" rel="noopener" data-cta="share" data-where="whatsapp">Share on WhatsApp</a></div></section>\n' + CTA_SECTION + "\n" +
    '<aside class="related"><h3>Keep reading</h3><ul>' + p.related.map(([h, l]) => '<li><a href="' + h + '">' + l + "</a></li>").join("") + "</ul></aside>\n" + (p.script ? "<script>" + p.script + "</script>\n" : "") + "</main>\n";
  return head + body + FOOT;
}
const REL_DEFAULT = [["/invoice-app-nigeria/", "Invoice app for Nigerian businesses"], ["/guides/how-to-write-an-invoice-in-nigeria/", "How to write an invoice in Nigeria"], ["/guides/payment-reminder-messages-nigeria/", "Payment reminder messages"], ["/guides/"," All guides"]];

