page({ path: "/delivery-note-maker/", crumb: "Waybill and delivery note maker", crumbs: [["/", "Home"]], kind: "product", title: "Waybill and Delivery Note Maker for Nigerian Businesses", desc: "Make a waybill or delivery note on your phone: items and quantities, rider or driver details, and a \"received in good condition\" line. Free to start.", h1: "A waybill and delivery note maker for businesses that deliver", read: 3, og: "delivery-note-vs-invoice",
  lead: "A waybill, also called a delivery note, lists what you sent, who is carrying it and who should receive it. With Aurum you make one on your phone in a minute, or start it from an invoice in one tap, and the customer signs that the goods arrived in good condition.",
  sections: [
    { h2: "What goes on a waybill", html: "<ul><li><b>Your business:</b> name, logo, address and phone number.</li><li><b>The receiver:</b> name, address and phone number.</li><li><b>The goods:</b> each item with its quantity. A waybill does not need prices.</li><li><b>Who is carrying it:</b> the rider, driver or vehicle, and the dispatch date.</li><li><b>Proof of receipt:</b> a line for the receiver to confirm the goods arrived in good condition, with a name, signature and date.</li></ul>" },
    { h2: "Start from an invoice in one tap", html: "<p>If you already made an invoice for the order, you do not retype anything. In Aurum, open the invoice and make a delivery note from it. The items and the customer are copied across, and you add the rider and the dispatch date.</p><p>You can send it as a private link, a PDF or an image, the same way as an invoice.</p>" },
    { h2: "Proof of delivery", html: "<p>Most delivery disputes are about one thing: did it arrive, and was it in good condition? A signed waybill answers both. Keep a copy of every one. When a customer says an item never came, you can show the date, the rider and the signature.</p>" },
    { h2: "Who uses it", html: "<ul><li><b>Online sellers</b> who send orders by dispatch rider or park.</li><li><b>Logistics and dispatch businesses</b> that carry goods for other people.</li><li><b>Wholesalers and distributors</b> who deliver in bulk and want the shop owner to sign.</li></ul>" },
  ],
  faq: [["Is a waybill the same as a delivery note?", "In Nigeria the two names are often used for the same document: a list of goods being delivered. Aurum calls it a delivery note and lets you title it Waybill."], ["Does a delivery note need prices?", "No. It lists items and quantities. Prices belong on the invoice."], ["Can the customer sign on their phone?", "A delivery note has a printed line for the receiver's name and signature. You can send it as a PDF or image to print, or collect the signature on paper and keep a photo."]],
  related: [["/guides/waybill-template-nigeria/", "Waybill in Nigeria: meaning, sample and template"], ["/guides/delivery-note-vs-invoice/", "Delivery note vs invoice"], ["/invoice-app-nigeria/", "Invoice app for Nigerian businesses"]] });

page({ path: "/purchase-order-maker/", crumb: "LPO and purchase order maker", crumbs: [["/", "Home"]], kind: "product", title: "LPO and Purchase Order Maker for Nigerian Businesses", desc: "Make an LPO or purchase order on your phone: supplier, items, agreed prices, deliver-by date and a supplier acknowledgement line. Free to start.", h1: "An LPO and purchase order maker for small businesses", read: 3, og: "purchase-order-explained",
  lead: "A purchase order, often called an LPO in Nigeria, is your written order to a supplier at an agreed price. With Aurum you make one on your phone with your logo, the deliver-by date and your delivery address, and the supplier acknowledges it.",
  sections: [
    { h2: "What goes on an LPO", html: "<ul><li><b>Your business:</b> name, address and contact, so the supplier knows who is ordering.</li><li><b>The supplier:</b> name and address.</li><li><b>The items:</b> description, quantity and the agreed unit price, with the total.</li><li><b>Delivery:</b> where to deliver and the deliver-by date.</li><li><b>Acknowledgement:</b> a line for the supplier to confirm they accept the order.</li></ul>" },
    { h2: "Why order in writing", html: "<p>A written order protects both sides. You have the price you agreed. The supplier has proof of what you asked for. When the invoice arrives you can check it against the LPO line by line, and when a delivery is short you know exactly what was promised.</p>" },
    { h2: "From LPO to invoice to receipt", html: "<p>The usual order is: you send an LPO, the supplier delivers with a waybill, then sends an invoice that quotes the LPO number, and you pay and receive a receipt. If you also sell, your own customers' LPOs come to you the same way. Put their LPO number on your invoice so their accounts team can match it.</p>" },
  ],
  faq: [["What does LPO stand for?", "LPO stands for local purchase order. It is the same idea as a purchase order, and in Nigeria the short name is more common."], ["Do I need an LPO for a small purchase?", "No rule says you must, but writing down what you ordered and the agreed price costs a minute and avoids arguments."], ["Can I make an LPO from my phone?", "Yes. Aurum makes purchase orders with your logo, the supplier details, the items, a deliver-by date and an acknowledgement line."]],
  related: [["/guides/lpo-local-purchase-order-nigeria/", "LPO in Nigeria: meaning, sample and how to respond"], ["/guides/purchase-order-explained/", "Purchase orders explained"], ["/invoice-app-nigeria/", "Invoice app for Nigerian businesses"]] });

page({ path: "/proforma-invoice-maker/", crumb: "Proforma invoice maker", crumbs: [["/", "Home"]], kind: "product", title: "Proforma Invoice Maker for Nigerian Businesses | Aurum", desc: "Make a proforma invoice on your phone, with your logo and bank details. When the customer agrees, turn it into an invoice in one tap. Free to start.", h1: "A proforma invoice maker for Nigerian businesses", read: 3, og: "proforma-invoice-nigeria",
  lead: "A proforma invoice shows a customer exactly what the final invoice will say, before you supply anything. In Aurum you make an invoice, set its title to \"Proforma Invoice\", and send it as a private link or a PDF. When the customer agrees, you issue the real invoice and, later, the receipt.",
  sections: [
    { h2: "What goes on a proforma invoice", html: "<ul><li>Your business name, logo and contact details, and the customer's.</li><li>Each item with its quantity and price, plus delivery and VAT if you charge them.</li><li>The title \"Proforma Invoice\", so nobody mistakes it for a bill to pay yet.</li><li>How long the prices are held, and how to pay the deposit if one is needed.</li></ul>" },
    { h2: "How to make one in Aurum", html: "<ol><li>Open Aurum and tap <b>New invoice</b>.</li><li>Add your customer and your items, as for any invoice.</li><li>On the last step, open <b>Customise</b> and choose the title <b>Proforma Invoice</b>.</li><li>Create the private link, or download the PDF, and send it on WhatsApp.</li><li>When the customer agrees, make the final invoice from it and send that.</li></ol>" },
    { h2: "From proforma to invoice to receipt", html: "<p>A proforma is a preview. The invoice is the request for payment, and the receipt is the proof that you were paid. Keeping the three separate keeps your records clean, and customers who need a proforma to arrange payment or clear goods get exactly what they asked for.</p>" },
  ],
  faq: [["Is a proforma invoice the same as a quotation?", "They are close. A quotation is an offer of a price. A proforma invoice looks like the final invoice and is often asked for by a customer's finance team, or to arrange payment. Aurum makes both."], ["Can a proforma invoice be used to pay?", "A customer can pay a deposit against it if you ask for one, but the invoice you issue afterwards is the document that records what is owed."]],
  related: [["/guides/proforma-invoice-nigeria/", "Proforma invoice in Nigeria"], ["/quotation-maker-nigeria/", "Quotation maker"], ["/invoice-app-nigeria/", "Invoice app for Nigerian businesses"]] });

