page({ path: "/tools/vat-calculator-nigeria/", crumb: "VAT calculator", crumbs: [["/", "Home"], ["/tools/", "Free tools"]], kind: "tool", noMid: true, title: "VAT Calculator Nigeria (7.5%): Add or Remove VAT", desc: "Add 7.5% VAT to a price, or find the VAT inside a price that already includes it. Free Nigeria VAT calculator in naira, with the formula shown.", h1: "Nigeria VAT calculator", read: 2,
  lead: "Type an amount in naira. The calculator adds 7.5% VAT to a price, or works out how much VAT is inside a price that already includes it.",
  sections: [
    { h2: "Calculate", html: '<div class="doc"><p><label for="v-amt"><b>Amount (₦)</b></label><br><input id="v-amt" inputmode="decimal" placeholder="100000" style="width:100%;padding:12px;font-size:17px;border:1px solid #cdbf9f;border-radius:10px"></p><p><label><input type="radio" name="v-mode" value="add" checked> Add VAT to this price</label><br><label><input type="radio" name="v-mode" value="remove"> This price already includes VAT</label></p><div id="v-out" aria-live="polite" style="font-size:17px"></div></div>' + TOOL_NOTE },
    { h2: "The formulas", html: "<p><b>To add VAT:</b> VAT = price × 0.075, and total = price × 1.075.</p><p><b>To remove VAT:</b> price before VAT = total ÷ 1.075, and VAT = total − price before VAT.</p>" },
    { h2: "A worked example", html: "<p>₦100,000 plus VAT is ₦107,500, because the VAT is ₦7,500. Going the other way, a total of ₦107,500 contains ₦7,500 VAT, and the price before VAT is ₦100,000.</p>" },
  ],
  disclaimer: "Not every business charges VAT, and small businesses may be exempt from charging or filing it. This tool is a calculator, not tax advice. Confirm your own situation with an accountant or the Nigeria Revenue Service.",
  faq: [["What is the VAT rate in Nigeria?", "The standard VAT rate in Nigeria is 7.5%. This calculator keeps the rate in one place, so it is easy to update if the law changes."], ["Do I have to charge VAT on my invoices?", "Not every business does. If you are unsure, ask an accountant. In Aurum you can switch VAT on or off for each invoice."]],
  related: [["/guides/vat-on-invoices-nigeria/", "VAT on invoices in Nigeria"], ["/tools/amount-in-words-naira/", "Naira amount in words"], ["/invoice-app-nigeria/", "Invoice app for Nigerian businesses"]],
  script: '(function(){var RATE=0.075,a=document.getElementById("v-amt"),o=document.getElementById("v-out");function f(n){return "₦"+n.toLocaleString("en-NG",{minimumFractionDigits:2,maximumFractionDigits:2})}function run(){var v=parseFloat(String(a.value).replace(/,/g,""));if(!isFinite(v)||v<=0){o.innerHTML="";return}var m=document.querySelector("input[name=v-mode]:checked").value;if(m==="add"){var vat=Math.round(v*RATE*100)/100;o.innerHTML="<b>VAT ("+(RATE*100)+"%):</b> "+f(vat)+"<br><b>Total with VAT:</b> "+f(v+vat)}else{var base=Math.round(v/(1+RATE)*100)/100;o.innerHTML="<b>Price before VAT:</b> "+f(base)+"<br><b>VAT inside:</b> "+f(Math.round((v-base)*100)/100)}}a.addEventListener("input",run);document.querySelectorAll("input[name=v-mode]").forEach(function(r){r.addEventListener("change",run)})})();' });

page({ path: "/tools/amount-in-words-naira/", crumb: "Naira amount in words", crumbs: [["/", "Home"], ["/tools/", "Free tools"]], kind: "tool", noMid: true, title: "Naira Amount in Words Converter for Receipts and Cheques", desc: "Type a naira amount and get it in words, ready to copy onto a receipt, invoice or cheque. Handles millions, billions and kobo. Free.", h1: "Write a naira amount in words", read: 2,
  lead: "Receipts and cheques in Nigeria usually state the amount in words as well as figures. Type the figure and copy the words.",
  sections: [
    { h2: "Convert", html: '<div class="doc"><p><label for="w-amt"><b>Amount (₦)</b></label><br><input id="w-amt" inputmode="decimal" placeholder="1250500.50" style="width:100%;padding:12px;font-size:17px;border:1px solid #cdbf9f;border-radius:10px"></p><p id="w-out" aria-live="polite" style="font-size:18px;min-height:28px"></p><p><button class="btn" type="button" id="w-copy">Copy the words</button></p></div>' + TOOL_NOTE },
    { h2: "How the words are written", html: "<p>The words follow Nigerian and British style: commas between the groups, \"and\" before the last part, the naira first, then the kobo, and the word \"only\" at the end so nothing can be added.</p><p><b>Example:</b> ₦1,250,500.50 is \"One million, two hundred and fifty thousand, five hundred naira, fifty kobo only\".</p>" },
  ],
  faq: [["Why write the amount in words?", "Words are harder to change than figures, so they protect a receipt or cheque from being altered."], ["Does Aurum do this automatically?", "Yes. Aurum writes the amount in words on every invoice and receipt for you."]],
  related: [["/guides/receipt-template-nigeria/", "Receipt template for Nigeria"], ["/receipt-maker-nigeria/", "Receipt maker"], ["/tools/vat-calculator-nigeria/", "VAT calculator"]],
  script: '(function(){var ones=["","one","two","three","four","five","six","seven","eight","nine","ten","eleven","twelve","thirteen","fourteen","fifteen","sixteen","seventeen","eighteen","nineteen"],tens=["","","twenty","thirty","forty","fifty","sixty","seventy","eighty","ninety"],sc=["","thousand","million","billion","trillion"];function h(n){var s="";if(n>=100){s+=ones[Math.floor(n/100)]+" hundred";n%=100;if(n)s+=" and "}if(n>=20){s+=tens[Math.floor(n/10)];if(n%10)s+="-"+ones[n%10]}else if(n>0)s+=ones[n];return s}function words(n){if(n===0)return "zero";var g=[],i=0;while(n>0){g.push(n%1000);n=Math.floor(n/1000)}var parts=[];for(i=g.length-1;i>=0;i--){if(!g[i])continue;var p=h(g[i])+(sc[i]?" "+sc[i]:"");if(i===0&&g.length>1&&g[0]<100)p="and "+p;parts.push(p)}return parts.join(", ").replace(", and ", " and ")}function cap(s){return s.charAt(0).toUpperCase()+s.slice(1)}var a=document.getElementById("w-amt"),o=document.getElementById("w-out");function run(){var raw=String(a.value).replace(/,/g,"").trim();var v=parseFloat(raw);if(!isFinite(v)||v<0||v>999999999999999){o.textContent="";return}var naira=Math.floor(v),kobo=Math.round((v-naira)*100);if(kobo===100){naira++;kobo=0}var t=(naira===0&&kobo?cap(words(kobo))+" kobo":cap(words(naira))+" naira"+(kobo?", "+words(kobo)+" kobo":""))+" only";o.textContent=t}a.addEventListener("input",run);document.getElementById("w-copy").addEventListener("click",function(){if(o.textContent&&navigator.clipboard)navigator.clipboard.writeText(o.textContent)})})();' });

page({ path: "/tools/payment-reminder-message-generator/", crumb: "Payment reminder generator", crumbs: [["/", "Home"], ["/tools/", "Free tools"]], kind: "tool", noMid: true, title: "Payment Reminder Message Generator for WhatsApp (Free)", desc: "Fill in the client's name, the amount and the due date, choose a tone, and copy a polite payment reminder to send on WhatsApp. Free, no account.", h1: "Write a polite payment reminder in seconds", read: 2,
  lead: "Asking for your money is uncomfortable, so most people leave it too late. Fill in four details, choose how firm you want to be, and copy a message you can send on WhatsApp now.",
  sections: [
    { h2: "Make your message", html: '<div class="doc"><p><label for="r-name"><b>Client\'s name</b></label><br><input id="r-name" placeholder="Mrs Okafor" style="width:100%;padding:12px;font-size:17px;border:1px solid #cdbf9f;border-radius:10px"></p><p><label for="r-amt"><b>Amount (₦)</b></label><br><input id="r-amt" inputmode="decimal" placeholder="150000" style="width:100%;padding:12px;font-size:17px;border:1px solid #cdbf9f;border-radius:10px"></p><p><label for="r-inv"><b>Invoice number</b> (optional)</label><br><input id="r-inv" placeholder="INV-0042" style="width:100%;padding:12px;font-size:17px;border:1px solid #cdbf9f;border-radius:10px"></p><p><label for="r-due"><b>Due date</b> (optional)</label><br><input id="r-due" type="date" style="width:100%;padding:12px;font-size:17px;border:1px solid #cdbf9f;border-radius:10px"></p><p><b>Tone</b><br><label><input type="radio" name="r-tone" value="0" checked> Gentle</label> &nbsp; <label><input type="radio" name="r-tone" value="1"> Due today</label> &nbsp; <label><input type="radio" name="r-tone" value="2"> Overdue</label> &nbsp; <label><input type="radio" name="r-tone" value="3"> Final notice</label></p><div class="script" id="r-out"></div><p><button class="btn primary" type="button" id="r-copy">Copy message</button> <a class="btn" id="r-wa" target="_blank" rel="noopener" href="https://wa.me/">Open in WhatsApp</a></p></div>' + TOOL_NOTE },
    { h2: "Which tone to use", html: "<p>Start gentle a few days before the due date. Use \"due today\" on the day. If a week has passed, say plainly that it is overdue. Keep the final notice for when earlier messages were ignored, and offer a payment plan if the client is struggling.</p>" },
  ],
  faq: [["Is it rude to remind a customer about payment?", "No. A courteous reminder is normal in business, and most customers appreciate it."], ["Can Aurum send reminders for me?", "On the Pro plan, Aurum tells you each morning who to remind, with the message ready for WhatsApp, and can email your client too."]],
  related: [["/guides/payment-reminder-messages-nigeria/", "Payment reminder messages (more examples)"], ["/guides/how-to-get-paid-on-time-nigeria/", "How to get paid on time"], ["/whatsapp-invoice/", "Send invoices on WhatsApp"]],
  script: '(function(){var $=function(i){return document.getElementById(i)};function money(v){var n=parseFloat(String(v).replace(/,/g,""));return isFinite(n)&&n>0?"₦"+n.toLocaleString("en-NG"):"₦[amount]"}function day(s){if(!s)return"";var d=new Date(s+"T12:00:00");return d.toLocaleDateString("en-GB",{day:"numeric",month:"long",year:"numeric"})}function msg(){var n=$("r-name").value.trim()||"there",a=money($("r-amt").value),inv=$("r-inv").value.trim()||"[invoice number]",due=day($("r-due").value),t=document.querySelector("input[name=r-tone]:checked").value;var T=["Hello "+n+", I hope you\\u2019re well. This is a gentle reminder that "+a+" is still outstanding on invoice "+inv+(due?", due on "+due:"")+".\\n\\nThank you!","Hello "+n+", just a quick reminder that invoice "+inv+" ("+a+") is due today.\\n\\nThank you for your prompt payment.","Hello "+n+", invoice "+inv+" for "+a+" is now overdue. Kindly make payment at your earliest convenience, or let us know if there\\u2019s any issue.\\n\\nThank you.","Dear "+n+", this is a final reminder that invoice "+inv+" for "+a+" remains unpaid. Please pay as soon as you can. If you need to discuss a payment plan, reply today.\\n\\nThank you."];return T[t]}function run(){var m=msg();$("r-out").textContent=m;$("r-wa").href="https://wa.me/?text="+encodeURIComponent(m)}["r-name","r-amt","r-inv","r-due"].forEach(function(i){$(i).addEventListener("input",run)});document.querySelectorAll("input[name=r-tone]").forEach(function(r){r.addEventListener("change",run)});$("r-copy").addEventListener("click",function(){if(navigator.clipboard)navigator.clipboard.writeText($("r-out").textContent)});run()})();' });

/* ------------------------------------------------------------------ Phase C: guides */
const G = (o) => page({ crumbs: [["/", "Home"], ["/guides/", "Guides"]], kind: "guide", read: 3, related: REL_DEFAULT, ...o, path: "/guides/" + o.slug + "/", og: o.og || "guides" });
G({ slug: "waybill-template-nigeria", crumb: "Waybill in Nigeria", title: "Waybill in Nigeria: Meaning, Sample and Free Template", desc: "What a waybill is in Nigeria, what to write on it, a sample you can copy, and how it differs from an invoice and a receipt.", h1: "Waybill in Nigeria: meaning, sample and free template",
  lead: "A waybill is a document that travels with goods. It says what is being sent, who is sending it, who should receive it and who is carrying it. In Nigeria it is also called a delivery note.",
  sections: [
    { h2: "What a waybill is", html: "<p>A waybill lists the goods in a delivery. It is not a bill. It does not ask for payment. Its job is to prove what was sent, when, and who received it.</p>" },
    { h2: "What to write on a waybill", html: "<ul><li>Sender: business name, address and phone.</li><li>Receiver: name, address and phone.</li><li>Waybill number and dispatch date.</li><li>Each item and its quantity. Prices are not needed.</li><li>Rider, driver or vehicle details.</li><li>A line for the receiver: \"Received in good condition\", name, signature and date.</li></ul>" },
    { h2: "A waybill sample", html: '<div class="doc"><h4>Waybill WB-0015</h4><p><b>From:</b> Adaeze Couture, Lekki, Lagos · 0801 234 5678<br><b>To:</b> Mrs Okafor, 12 Admiralty Way, Lekki · 0803 555 1234<br><b>Dispatched:</b> 16 November 2026 · <b>Rider:</b> Tunde, plate LND 224 XA</p><table class="ex"><tr><th>Item</th><th class="r">Qty</th></tr><tr><td>Ankara day dress, size 12</td><td class="r">2</td></tr><tr><td>Aso-oke gele</td><td class="r">1</td></tr></table><p>Received in good condition by: ______________ Signature: ________ Date: ________</p></div>' },
    { h2: "Waybill, invoice and receipt", html: "<p>The <b>waybill</b> proves delivery. The <b>invoice</b> asks for payment. The <b>receipt</b> proves payment. Many businesses send all three for one order. Aurum makes each from the one before, so the details are never retyped.</p>" },
  ],
  faq: [["Is a waybill the same as a delivery note?", "In Nigeria people use both names for the same document."], ["Does a waybill need prices?", "No. List the items and quantities. Put prices on the invoice."], ["Who keeps the waybill?", "The sender keeps a copy and the receiver signs one. Keep yours so you can prove delivery."]],
  related: [["/delivery-note-maker/", "Waybill and delivery note maker"], ["/guides/delivery-note-vs-invoice/", "Delivery note vs invoice"], ["/invoice-app-nigeria/", "Invoice app for Nigerian businesses"]] });
G({ slug: "lpo-local-purchase-order-nigeria", crumb: "LPO in Nigeria", title: "LPO in Nigeria: Meaning, Sample and How to Respond", desc: "What an LPO (local purchase order) is, what it should contain, a sample, and what a supplier should do after receiving one.", h1: "LPO in Nigeria: meaning, sample and how to respond",
  lead: "An LPO is a local purchase order: a written order from a buyer to a supplier, at an agreed price. Companies and organisations in Nigeria often will not pay an invoice unless it matches an LPO.",
  sections: [
    { h2: "What an LPO contains", html: "<ul><li>The buyer's name, address and an LPO number.</li><li>The supplier's name and address.</li><li>The items, quantities and agreed prices, with the total.</li><li>Where and by when to deliver.</li><li>Who approved the order.</li></ul>" },
    { h2: "A sample LPO", html: '<div class="doc"><h4>LPO 0087</h4><p><b>Buyer:</b> Sunrise Schools Ltd · <b>Supplier:</b> Adaeze Couture · <b>Deliver by:</b> 30 November 2026</p><table class="ex"><tr><th>Description</th><th class="r">Qty</th><th class="r">Price</th><th class="r">Amount</th></tr><tr><td>School uniform, set</td><td class="r">40</td><td class="r">₦18,000</td><td class="r">₦720,000</td></tr></table><p>Approved by: ______________ Date: ________</p></div>' },
    { h2: "What a supplier should do after receiving an LPO", html: "<ol><li>Check the items, quantities and prices are what you agreed.</li><li>Confirm you accept it, in writing or by signing the acknowledgement line.</li><li>Deliver with a waybill that quotes the LPO number.</li><li>Send an invoice that quotes the LPO number, so the buyer's accounts team can match it and pay.</li></ol>" },
  ],
  faq: [["Does an LPO mean I will be paid?", "An LPO is a commitment to buy at the agreed price. Payment still follows your invoice and the payment terms, so state them clearly."], ["What if the LPO price is wrong?", "Tell the buyer before you deliver and ask for a corrected LPO."]],
  related: [["/purchase-order-maker/", "LPO and purchase order maker"], ["/guides/purchase-order-explained/", "Purchase orders explained"], ["/guides/how-to-invoice-a-company-in-nigeria/", "How to invoice a company in Nigeria"]] });
G({ slug: "rent-receipt-nigeria", crumb: "Rent receipt in Nigeria", title: "House Rent Receipt Sample for Nigeria (Free Template)", desc: "A rent receipt sample for Nigerian landlords and agents: what it must show, the period covered, and a template you can copy.", h1: "House rent receipt sample for Nigeria",
  lead: "A rent receipt is the tenant's proof that they paid. For a landlord or agent it is also the record that stops arguments about what was paid and for which period.",
  sections: [
    { h2: "What a rent receipt must show", html: "<ul><li>The tenant's name and the property address.</li><li>The amount paid, in figures and in words.</li><li>The period the rent covers, for example 1 January 2027 to 31 December 2027.</li><li>How it was paid: transfer, cash or cheque, and the date.</li><li>Who received it, with a name and signature.</li></ul>" },
    { h2: "A rent receipt sample", html: '<div class="doc"><h4>Receipt R-0031</h4><p>Received from <b>Mr Bello Adeyemi</b> the sum of <b>₦1,800,000</b> (One million, eight hundred thousand naira only), being rent for <b>Flat 3, 14 Allen Avenue, Ikeja</b> for the period <b>1 January 2027 to 31 December 2027</b>.</p><p>Paid by bank transfer on 12 December 2026.<br>Received by: ______________ (Landlord / Agent)</p></div>' },
    { h2: "Keep it separate from other payments", html: "<p>If the tenant also pays a caution deposit, agency fee or service charge, give each its own line or its own receipt. A single mixed amount is the usual cause of disagreements later.</p>" },
  ],
  faq: [["Should I give a receipt for a bank transfer?", "Yes. A transfer alert shows money moved, but your receipt says what it was for and for which period."], ["Can I make a rent receipt on my phone?", "Yes. Aurum makes receipts with your logo, the amount in words and a Paid stamp, and sends them as a private link, PDF or image."]],
  related: [["/receipt-maker-nigeria/", "Receipt maker"], ["/guides/receipt-template-nigeria/", "Receipt template for Nigeria"], ["/tools/amount-in-words-naira/", "Naira amount in words"]] });
G({ slug: "how-to-invoice-a-company-in-nigeria", crumb: "Invoice a company", title: "How to Invoice a Company in Nigeria and Get Paid", desc: "What companies need on your invoice before they pay: LPO number, TIN, bank details, the right contact, and how to follow up.", h1: "How to invoice a company in Nigeria and get paid",
  lead: "Companies pay through an accounts process, not a quick transfer. An invoice that has what that process needs is paid sooner than one that has to be sent back.",
  sections: [
    { h2: "What a company usually needs on your invoice", html: "<ul><li>The company's exact registered name and address.</li><li>The LPO or contract number, if there is one.</li><li>Your business name, address, TIN if you have one, and bank account name matching your business.</li><li>A clear description of the work or goods, with dates.</li><li>The payment terms and the due date.</li></ul>" },
    { h2: "Send it to the right person", html: "<p>Ask who receives invoices. It is often an accounts officer, not the person who gave you the job. Send it to both, and ask for a reply that confirms it was received.</p>" },
    { h2: "Follow up without being awkward", html: "<p>Companies often pay on a schedule, so ask when the next payment run is. Remind a few days before the due date, then on the day. Keep every message polite and short, and always include the invoice link or number.</p>" },
  ],
  faq: [["What if the company pays less than my invoice?", "Ask for a written explanation. Companies sometimes deduct taxes or fees, so keep the paperwork that shows what was deducted."], ["How long do companies take to pay?", "It depends on their terms. Agree the payment terms before you start, and put them on the invoice."]],
  related: [["/guides/lpo-local-purchase-order-nigeria/", "LPO in Nigeria"], ["/guides/late-payment-fee-and-payment-terms/", "Late payment fees and payment terms"], ["/guides/payment-reminder-messages-nigeria/", "Payment reminder messages"]] });
G({ slug: "invoice-app-vs-excel-template", crumb: "Invoice app or Excel", title: "Invoice App or Excel Template: Which Should You Use?", desc: "An honest comparison of invoice apps and Excel or Word templates for a small Nigerian business, with when each one makes sense.", h1: "Invoice app or Excel template: which should you use?",
  lead: "Both work. The right choice depends on how many documents you send and how much time you want to spend on them.",
  sections: [
    { h2: "When a template is enough", html: "<p>If you send one or two invoices a month, a free Excel or Word template is enough. You fill it in, save it as a PDF and send it. It costs nothing and you control it. There are free invoice and receipt templates on our <a href=\"/guides/\">guides</a> that you can download.</p>" },
    { h2: "When an app starts to help", html: "<ul><li><b>You send many documents.</b> An app remembers your customers and prices, so you stop retyping.</li><li><b>You want to know it arrived.</b> A private link tells you when the client opens it.</li><li><b>You chase payments.</b> An app shows who still owes you and helps you remind them.</li><li><b>You use your phone.</b> Most spreadsheets are awkward on a phone.</li></ul>" },
    { h2: "Where the risks are", html: "<p>With a template, the risk is mistakes and lost files: a wrong total, a copied number or a document nobody can find later. With an app, the risk is depending on a service. Choose one that lets you export your records.</p>" },
  ],
  faq: [["Is Aurum free?", "Yes, for 5 documents a month. Paid plans add more documents, designs and reminders."], ["Can I move from Excel to an app later?", "Yes. Start with a template and move when the time you spend on invoices starts to feel like too much."]],
  related: [["/guides/invoice-template-nigeria/", "Invoice template for Nigeria"], ["/guides/best-invoice-app-for-small-business-nigeria/", "Best invoice app for small business in Nigeria"], ["/invoice-app-nigeria/", "Invoice app for Nigerian businesses"]] });
G({ slug: "receipt-book-vs-digital-receipts", crumb: "Receipt book or digital", title: "Receipt Book or Digital Receipts: Which Is Better?", desc: "Paper receipt booklets compared with digital receipts for Nigerian businesses: cost, trust, record keeping and what customers prefer.", h1: "Receipt book or digital receipts: which is better?",
  lead: "A receipt book is familiar and costs a few hundred naira. A digital receipt is faster to send and easier to keep. Here is how they compare.",
  sections: [
    { h2: "Paper receipt books", html: "<ul><li><b>Good:</b> cheap, no phone or data needed, and customers know them.</li><li><b>Not so good:</b> they get lost, the carbon copy fades, you cannot search them, and you must be there to write one.</li></ul>" },
    { h2: "Digital receipts", html: "<ul><li><b>Good:</b> sent in seconds on WhatsApp, always legible, searchable, backed up, and they can carry your logo and a QR code to show they are genuine.</li><li><b>Not so good:</b> you need a phone, and some customers still want paper.</li></ul>" },
    { h2: "A sensible middle", html: "<p>Many businesses give a digital receipt for every sale and print one only when a customer asks. That way you keep a clean record without a pile of booklets.</p>" },
  ],
  faq: [["Is a digital receipt valid?", "A receipt is proof that you received payment. A clear digital receipt with the amount, date, payer and what it was for does that job."], ["Can I print a digital receipt?", "Yes. Download it as a PDF and print it."]],
  related: [["/receipt-maker-nigeria/", "Receipt maker"], ["/guides/receipt-template-nigeria/", "Receipt template for Nigeria"], ["/guides/invoice-vs-receipt-vs-quotation/", "Invoice vs receipt vs quotation"]] });
G({ slug: "school-fees-receipt-sample", crumb: "School fees receipt", title: "School Fees Receipt Sample for Nigerian Schools", desc: "A school fees receipt sample: pupil, class, term, fees paid, balance, and how schools can issue receipts quickly on a phone.", h1: "School fees receipt sample for Nigerian schools",
  lead: "Parents pay school fees in parts, often by transfer. A clear receipt for each payment saves the bursar and the parent from arguments later.",
  sections: [
    { h2: "What a school fees receipt should show", html: "<ul><li>The school's name and the receipt number.</li><li>The pupil's name and class, and the term and session.</li><li>The amount paid, in figures and in words, the date and how it was paid.</li><li>What it was for: tuition, books, uniform, transport.</li><li>The balance still owing, if any, and who received the payment.</li></ul>" },
    { h2: "A school fees receipt sample", html: '<div class="doc"><h4>Receipt SF-0112</h4><p>Received from <b>Mrs Ngozi Eze</b> the sum of <b>₦150,000</b> (One hundred and fifty thousand naira only), being part payment of school fees for <b>Chidi Eze, Primary 4</b>, <b>First Term 2026/2027</b>.</p><p>Total fees ₦320,000 · Paid today ₦150,000 · <b>Balance ₦170,000</b><br>Paid by bank transfer on 20 September 2026.</p></div>' },
    { h2: "Issue them in seconds", html: "<p>In Aurum a school makes a receipt in one tap from the invoice, and the balance updates by itself after each part payment. Send it to the parent on WhatsApp as a private link.</p>" },
  ],
  faq: [["Should I give a receipt for part payments?", "Yes. Give one for every payment and show the balance, so both sides always agree."], ["Can parents verify a receipt?", "Aurum receipts can carry a QR code that confirms the receipt came from the school."]],
  related: [["/receipt-maker-nigeria/", "Receipt maker"], ["/guides/deposit-and-part-payment-invoice/", "Deposits and part payments"], ["/guides/rent-receipt-nigeria/", "Rent receipt sample"]] });
G({ slug: "how-to-price-your-services-nigeria", crumb: "Price your services", title: "How to Price Your Services in Nigeria", desc: "A simple way for Nigerian freelancers and service businesses to set prices: costs, time, deposit, and how to present the price.", h1: "How to price your services in Nigeria",
  lead: "Many people price by guessing what the client will accept. A simple method gives you a price you can defend and still make money.",
  sections: [
    { h2: "Start with your costs", html: "<p>Add up what the job really costs you: materials, transport, data, helpers, and the time you spend, including time you do not see such as messages and travel. If you do not count your time, you are working for free.</p>" },
    { h2: "Add what you want to earn", html: "<p>Decide a fair hourly or daily rate for your skill, multiply by the hours the job needs, add the costs, and add a small cushion for things that go wrong. That is your starting price.</p>" },
    { h2: "Present it clearly", html: "<ul><li>Break the price into lines so the client sees what each part covers.</li><li>Ask for a deposit before you start.</li><li>State what is included and what costs extra.</li><li>Say how long the price is valid.</li></ul>" },
  ],
  faq: [["What if the client says it is too expensive?", "Offer a smaller scope at a lower price instead of cutting your rate for the same work."], ["Should I show my prices publicly?", "Showing a starting price saves time, because people who cannot afford you do not enquire."]],
  related: [["/quotation-maker-nigeria/", "Quotation maker"], ["/guides/quotation-template-nigeria/", "Quotation template for Nigeria"], ["/guides/deposit-and-part-payment-invoice/", "Deposits and part payments"]] });

require("./guides-legal")(G);

/* trade pages */
const TRADES = [
  ["logistics-and-dispatch-riders", "Logistics and Dispatch Riders", "per-delivery and bulk pricing, waybills, pay-on-delivery remittance and weekly statements", "A dispatch business charges by the delivery, the distance or the month. Your invoice should show which, and your waybills should back it up.", ["Price per delivery, per distance band or a bulk monthly rate, shown as separate lines.", "A waybill number for every delivery, so the customer can match each charge.", "Pay-on-delivery cash you collected for a customer, kept as its own line and its own remittance.", "A weekly statement for regular customers, instead of one invoice per drop."], [["Delivery within Lekki (20 drops)", "20", "₦2,000", "₦40,000"], ["Delivery to mainland (8 drops)", "8", "₦3,500", "₦28,000"]]],
  ["real-estate-agents", "Real Estate Agents", "agency and legal fees, caution deposit, rent receipts and payment by instalment", "Agents handle several kinds of money in one deal. Keep each kind on its own line so nobody confuses fees with rent or deposits.", ["Agency fee and legal fee as separate lines, each with its percentage or amount.", "Caution deposit shown separately, because it may be refundable.", "A rent receipt for every rent payment, with the period it covers.", "A clear instalment schedule if the client pays in parts."], [["Agency fee (10%)", "1", "₦180,000", "₦180,000"], ["Legal fee (10%)", "1", "₦180,000", "₦180,000"]]],
  ["bakers-and-food-vendors", "Bakers and Food Vendors", "deposits before baking, delivery fee, bulk and event orders and order confirmation", "A custom cake or a big food order is made for one customer, so you cannot sell it twice if they back out. Take a deposit and confirm the order in writing.", ["A deposit before you start, with the balance due before delivery.", "A delivery fee as its own line.", "Quantities and sizes written clearly, for example 2-tier cake, 60 puff-puff packs.", "The date and time of pickup or delivery, so the order is confirmed in writing."], [["2-tier celebration cake", "1", "₦85,000", "₦85,000"], ["Small chops (50 guests)", "1", "₦60,000", "₦60,000"]]],
  ["printing-and-branding-businesses", "Printing and Branding Businesses", "quotation first, design fee and print fee apart, quantity breaks and deposit before production", "Printing jobs change with quantity and design. Quote first, agree the details, then invoice, so you are not paying for a reprint.", ["Send a quotation first and invoice only after the customer approves the design.", "Design fee and print fee as separate lines.", "Prices for different quantities, for example 100, 500 and 1,000.", "A deposit before production, because the job cannot be resold."], [["Business cards, 500 pieces", "1", "₦22,000", "₦22,000"], ["Logo and card design", "1", "₦15,000", "₦15,000"]]],
  ["interior-designers", "Interior Designers", "design fee, materials and labour apart, stage payments and variations", "Interior jobs run for weeks and change as they go. Split the money into stages and record every change in writing.", ["The design fee as its own line.", "Materials and labour separated, so the client sees where the money goes.", "Stage payments: for example deposit, mid-way and handover.", "A variation note, with a new amount, whenever the client adds or changes something."], [["Design and 3D drawings", "1", "₦250,000", "₦250,000"], ["Living room fit-out, labour", "1", "₦400,000", "₦400,000"]]],
  ["auto-mechanics", "Auto Mechanics and Workshops", "parts and labour apart, estimate before work, deposit for parts and a warranty note", "Customers want to know what is parts and what is labour. Give an estimate first, and write down any warranty you give.", ["An estimate before you start, and a call before you exceed it.", "Parts and labour as separate lines.", "A deposit to buy parts, if they are expensive.", "A warranty note, for example 30 days on labour, so there are no arguments later."], [["Brake pads (front)", "1", "₦28,000", "₦28,000"], ["Labour: brake service", "1", "₦12,000", "₦12,000"]]],
  ["event-rental-businesses", "Event Rental Businesses", "hire period, refundable deposit, damage terms and delivery and pickup", "Rental items come back, so the invoice must say for how long, what is refundable and what happens if something is damaged.", ["The hire period with start and end dates.", "A refundable deposit shown as its own line.", "Damage and loss terms, in one clear sentence.", "Delivery and pickup as separate lines."], [["Chiavari chairs (200), 2 days", "200", "₦800", "₦160,000"], ["Delivery and pickup", "1", "₦25,000", "₦25,000"]]],
  ["cleaning-and-fumigation-services", "Cleaning and Fumigation Services", "one-off and monthly contracts, repeat invoices, site visits and materials", "Cleaning and fumigation are often repeat jobs. A clear contract and a repeat invoice keep monthly clients easy to manage.", ["One-off and monthly prices on separate lines.", "The site or address and the number of visits.", "Materials, if you charge for them, as their own line.", "A repeat invoice for monthly clients, so it is ready each month."], [["Office cleaning, 4 visits", "4", "₦30,000", "₦120,000"], ["Fumigation, 2-bedroom flat", "1", "₦45,000", "₦45,000"]]],
];
for (const [key, name, cover, intro, points, rows] of TRADES) {
  const slug = "invoice-for-" + key + "-nigeria", title = "Invoice for " + name + " in Nigeria (With Sample)";
  G({ slug, crumb: "Invoice for " + name.toLowerCase(), title: title.length > 60 ? "Invoice for " + name + " in Nigeria" : title, desc: "How " + name.toLowerCase() + " in Nigeria should invoice: " + cover.split(", ").slice(0, 3).join(", ").replace(/ and /g, ", ") + ", with a sample invoice.", h1: "How " + name.toLowerCase() + " in Nigeria should write an invoice", read: 2,
    lead: intro,
    sections: [
      { h2: "What to put on the invoice", html: "<ul>" + points.map((x) => "<li>" + x + "</li>").join("") + "</ul>" },
      { h2: "A sample invoice", html: '<table class="ex"><tr><th>Description</th><th class="r">Qty</th><th class="r">Price</th><th class="r">Amount</th></tr>' + rows.map(([d, q, p, a]) => "<tr><td>" + d + '</td><td class="r">' + q + '</td><td class="r">' + p + '</td><td class="r">' + a + "</td></tr>").join("") + "</table>" },
      { h2: "Make it quick and look premium", html: "<p>You send many similar invoices, so reuse your prices instead of retyping them. <a href=\"/invoice-app-nigeria/\">Aurum</a> keeps your logo, signature and bank details on every document, remembers your customers and prices, and sends the invoice as a private link your client opens like a gift. It is free for 5 documents a month.</p>" },
    ],
    faq: [["Should I take a deposit?", "For work that costs you money up front or cannot be resold, yes. State the deposit and the balance due date on the invoice."], ["Should I send a quotation first?", "For larger or changing jobs, yes. A quotation agrees the price before work starts, and you turn it into an invoice when the customer accepts."]],
    related: [["/guides/invoice-for-photographers-nigeria/", "Invoice for photographers in Nigeria"], ["/guides/deposit-and-part-payment-invoice/", "Deposits and part payments"], ["/quotation-maker-nigeria/", "Quotation maker"], ["/guides/", "All guides"]] });
}

/* ------------------------------------------------------------------ write the pages and update the shared files */
const written = [];
for (const p of pages) { const dir = path.join(ROOT, p.path.replace(/^\/|\/$/g, "")); fs.mkdirSync(dir, { recursive: true }); fs.writeFileSync(path.join(dir, "index.html"), render(p)); written.push(p); }
// sitemap
let sm = fs.readFileSync(path.join(ROOT, "sitemap.xml"), "utf8");
for (const p of written) { const loc = BASE + p.path; if (!sm.includes("<loc>" + loc + "</loc>")) sm = sm.replace("</urlset>", "<url><loc>" + loc + "</loc><lastmod>" + TODAY + "</lastmod><changefreq>monthly</changefreq><priority>" + (p.kind === "guide" ? "0.7" : "0.8") + "</priority></url>\n</urlset>"); }
sm = sm.replace(/(<loc>https:\/\/auruminvoice\.com\.ng\/<\/loc><lastmod>)[^<]*/, "$1" + TODAY);
fs.writeFileSync(path.join(ROOT, "sitemap.xml"), sm);
// llms.txt
let ll = fs.readFileSync(path.join(ROOT, "llms.txt"), "utf8");
const add = written.filter((p) => !ll.includes(BASE + p.path)).map((p) => "- [" + p.h1.replace(/\.$/, "") + "](" + BASE + p.path + "): " + p.desc).join("\n");
if (add) ll = ll.replace(/\s*$/, "\n") + "\n## More pages\n" + add + "\n"; fs.writeFileSync(path.join(ROOT, "llms.txt"), ll);
// guides hub: add the new guides
let gi = fs.readFileSync(path.join(ROOT, "guides/index.html"), "utf8");
const newG = written.filter((p) => p.kind === "guide" && !gi.includes(p.path));
if (newG.length) { const cards = newG.map((p) => '<a class="card" href="' + p.path + '"><b>' + p.h1 + "</b><span>" + p.desc + "</span></a>").join(""); gi = gi.replace(/(<\/div>\s*)(<section class="cta">|<aside class="related">|<section class="share">|<section class="cta)/, '<h2 id="more-guides">More guides</h2><div class="grid">' + cards + "</div>\n$2"); fs.writeFileSync(path.join(ROOT, "guides/index.html"), gi); }
/* live guides: one-line links to the new pages (added once) */
const NOTES = { "delivery-note-vs-invoice": ["In Nigeria a delivery note is often called a waybill. See our <a href=\"/guides/waybill-template-nigeria/\">waybill guide</a> and <a href=\"/delivery-note-maker/\">waybill maker</a>."], "purchase-order-explained": ["In Nigeria a purchase order is often called an LPO. See our <a href=\"/guides/lpo-local-purchase-order-nigeria/\">LPO guide</a> and <a href=\"/purchase-order-maker/\">LPO maker</a>."], "payment-reminder-messages-nigeria": ["Short on time? Use the <a href=\"/tools/payment-reminder-message-generator/\">free reminder message generator</a>."], "receipt-template-nigeria": ["Need the amount in words? Use the <a href=\"/tools/amount-in-words-naira/\">naira amount in words converter</a>. A cash receipt and a sales receipt use the same layout: who paid, how much, for what, and the date."], "vat-on-invoices-nigeria": ["Work out VAT quickly with the <a href=\"/tools/vat-calculator-nigeria/\">Nigeria VAT calculator</a>."], "proforma-invoice-nigeria": ["Make one on your phone with the <a href=\"/proforma-invoice-maker/\">proforma invoice maker</a>."], "invoice-template-nigeria": ["Printed invoice booklets are often called a cash invoice or a sales invoice. Aurum makes both: choose the title in Customise."] };
for (const [g, [html]] of Object.entries(NOTES)) {
  const f = path.join(ROOT, "guides", g, "index.html"); let t = fs.readFileSync(f, "utf8"); const marker = "<!-- more-links -->";
  if (t.includes(marker)) continue;
  const at = t.indexOf("</p>", t.indexOf('<p class="lead">')) + 4;
  t = t.slice(0, at) + "\n" + marker + "<p>" + html + "</p>" + t.slice(at); fs.writeFileSync(f, t);
}
console.log(written.length + " pages written");
